"""Proposed programming only: no performance forecast or confirmed new assets."""
import json,html,datetime as dt

def programme(out,make,head,note):
 p=json.loads((out/'post-album-plan.json').read_text());E=lambda x:html.escape(str(x),quote=True)
 assert len(p['weeks'])==8 and sum(w['shorts'] for w in p['weeks'])==16
 assert sum(w['anchor']=='proposed' for w in p['weeks'])==1
 assert sum(w['anchor']=='optional' for w in p['weeks'])==1
 assert all((dt.date.fromisoformat(w['date'])-dt.date.fromisoformat(p['start'])).days==i*7 for i,w in enumerate(p['weeks']))
 weeks=[]
 for i,w in enumerate(p['weeks']):
  cells=[]
  for day in range(7):
   kind='short' if day in (1,4) else (w['anchor'] if day==0 and w['anchor'] else 'empty')
   label={'short':'Proposed Short','proposed':'Proposed full performance — clearance required','optional':'Optional second full-length version — decision pending','empty':'No scheduled upload'}[kind]
   cells.append(f'<i class="plan-dot {kind}" role="img" aria-label="{label}"></i>')
  klass=' anchor-week' if w['anchor'] else ''
  weeks.append(f'<article class="plan-week{klass}"><header><span>W{i+1}</span><b>{E(w["label"])}</b></header><div class="plan-dots">'+''.join(cells)+f'</div><h3>{E(w["title"])}</h3><p>{E(w["support"])}</p><small>2 Shorts'+(' · full-length*' if w['anchor']=='proposed' else ' · optional full-length*' if w['anchor']=='optional' else '')+'</small></article>')
 timeline=head('Violins · proposed post-album programme · 23 Nov → 17 Jan','One new performance.<br><span class="serif">Keep the song moving around it.</span>')
 timeline+='''<div class="plan-prep"><b>18–22 Nov · first, clear the asset</b><span>Label + management confirm the full XMU take, permissions and edit delivery. Stone Fruit first; if unavailable, choose an approved alternative and reset the dates.</span></div><div class="plan-key"><span><i class="plan-dot proposed"></i>Proposed full-length</span><span><i class="plan-dot short"></i>2 Shorts / week</span><span><i class="plan-dot optional"></i>Optional second version</span><em>Week commencing · illustrative slots</em></div><div class="plan-calendar">'''+''.join(weeks)+'''</div><div class="plan-always"><b>Across all eight weeks</b><span>Olympus / Salad / Docket → Violins · playlists, end screens and Shorts Related Videos reviewed in Studio.</span></div><div class="plan-rule"><b>The programming rule</b><span>Give the full song a distinct supporting format inside <strong>7–14 days</strong>. Keep <strong>two purposeful Shorts a week</strong>; choose January’s full upload from response and available assets.</span></div>'''
 timeline+=note('INFERENCE · Proposed, not booked: 16 Shorts + one full-length upload, with a second full-length slot optional. Full XMU footage and rights are unconfirmed. 7–14 days is a planning test, not a proven optimum. No viewing forecast; Station access can be discussed with YouTube separately.')
 route=head('Post-album · the first song to develop','Start with Stone Fruit.<br><span class="serif">Give fans another way in.</span>')
 route+='''<div class="song-plan-grid mt"><article><span class="plan-step">01 / already available</span><a class="plan-photo" href="https://www.youtube.com/watch?v=7M9A_sVI4BI" target="_blank" rel="noopener"><img src="/blondshell/images/7M9A_sVI4BI.jpg" width="480" height="360" alt="Stone Fruit official music video"><span>Stone Fruit · official video</span></a><h3>Keep the film in view.</h3><p>97.5k lifetime views. A limited Watcher interval also records continued viewing; use this as a focus candidate.</p></article><article><span class="plan-step">02 / proposed full performance</span><a class="plan-photo" href="https://www.youtube.com/watch?v=h0bN0GGLJSQ" target="_blank" rel="noopener"><img src="/blondshell/images/h0bN0GGLJSQ.jpg" width="480" height="360" alt="Existing Stone Fruit XMU Short — source material to investigate, not a delivered full take"><span>Existing XMU Short · full take to clear</span></a><h3>Finish the performance journey.</h3><p>The excerpt exists. Ask for the full take; confirm broadcaster rights, sound, edit and artist approval before scheduling.</p></article><article class="plan-followup"><span class="plan-step">03 / inside 7–14 days</span><div class="plan-window"><b>7–14<span>days</span></b><div><span>performance moment</span><i>+</i><span>lyric or song story</span></div></div><h3>Two fresh reasons to listen.</h3><p>Choose distinct Shorts from the cleared material. Set the relevant full performance as the Related Video in Studio.</p></article></div><div class="plan-decision"><div><b>Day 7</b><span>Record day-7 public views; review retention and comments in Studio.</span></div><div><b>Day 28</b><span>Review traffic paths and subscriber contribution in Studio. Decide whether another full version is justified.</span></div></div>'''
 route+=note('API + WATCHER → INFERENCE. Stone Fruit is a focus candidate, not a verified fastest-growing song. XMU imagery shows a public Short only; no full recording is assumed available. A new stripped take or lyric edit requires approval. Review dates run from the actual full-upload date.')
 return {'song-plan':make('song-plan','Stone Fruit · the next destination',route),'roadmap':make('roadmap','Post-album plan · November to January',timeline)}
